PLAYBOOK_TEMPLATES = {
    "grub_single": {
        "title": "方式一：GRUB 单用户模式重置密码",
        "steps": [
            "重启进入 GRUB，按 e 编辑启动项",
            "linux 行末追加 rw init=/bin/bash，Ctrl+X 启动",
            "mount -o remount,rw /",
            "passwd {username}",
            "exec /sbin/init 重启并验证新密码",
        ],
    },
    "rescue": {
        "title": "方式二：救援模式重置密码",
        "steps": [
            "安装光盘/U盘启动，选择救援模式",
            "chroot /mnt/sysimage",
            "passwd {username}",
            "exit 后从硬盘重启",
        ],
    },
    "livecd": {
        "title": "方式三：LiveCD 重置密码（桌面版）",
        "steps": [
            "光盘/U盘进入 LiveCD",
            "mount 原系统根分区到 /mnt",
            "chroot /mnt 后 passwd {username}",
            "umount 并从硬盘重启",
        ],
    },
}

SYSTEM_MODES = {
    "desktop": ["grub_single", "livecd", "rescue"],
    "server": ["grub_single", "rescue"],
    "kylin_v11": ["grub_single", "rescue", "livecd"],
    "auto": ["grub_single", "rescue", "livecd"],
}

def run(**kwargs):
    user = (kwargs.get("username") or "目标用户").strip()
    st = (kwargs.get("system_type") or "auto").lower()
    mode = (kwargs.get("recovery_mode") or "auto").lower()
    modes = SYSTEM_MODES.get(st, SYSTEM_MODES["auto"]) if mode == "auto" else ([mode] if mode in PLAYBOOK_TEMPLATES else [])
    if not modes:
        return {"success": False, "error": "无效的 recovery_mode"}
    books = []
    for m in modes:
        t = PLAYBOOK_TEMPLATES[m]
        books.append({"mode": m, "title": t["title"], "steps": [s.format(username=user) for s in t["steps"]]})
    return {"success": True, "data": {"username": user, "system_type": st, "playbooks": books, "summary": f"已生成 {len(books)} 套密码恢复手册"}}
